pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 _value, bytes calldata _data) public {
        _value = bound(_value, 0, 10 ether);
        Receiver receiver = new Receiver();
        vm.deal(address(c), 10 ether);
        uint256 balanceBefore = address(receiver).balance;
        vm.prank(address(this));
        c.sendMoney(address(receiver), _value, _data);
        assertTrue(address(receiver).balance == balanceBefore + _value);
    }
}

contract Receiver {
    fallback() external payable {}
}
